import * as components from "./components/index.js";
import type { PropDef, PropDefs } from "./props.js";

const HEADER =
  "/* Generated by packages/design-system/scripts/build-prop-types.ts from src/catalog/components. Do not edit. */";

function isPropDefs(value: unknown): value is PropDefs {
  return (
    typeof value === "object" &&
    value !== null &&
    Object.values(value).every(
      (def) =>
        typeof def === "object" &&
        def !== null &&
        "type" in def &&
        "description" in def,
    )
  );
}

/** `menuPopupProps` → `MenuPopupOwnProps`. */
export function ownPropsName(exportName: string): string {
  const base = exportName.replace(/Props$/, "");
  return `${base.charAt(0).toUpperCase()}${base.slice(1)}OwnProps`;
}

function tsType(def: PropDef): string | null {
  if (def.type === "enum") {
    return def.values.map((value) => JSON.stringify(value)).join(" | ");
  }
  if (def.type === "boolean") return "boolean";
  return null;
}

function docComment(def: PropDef, indent: string): string {
  const lines = def.description.split("\n");
  if (def.type !== "string" && def.type !== "number" && "default" in def) {
    if (def.default !== undefined) {
      lines.push(`@default ${JSON.stringify(def.default)}`);
    }
  }
  return [
    `${indent}/**`,
    ...lines.map((line) => `${indent} * ${line}`.trimEnd()),
    `${indent} */`,
  ].join("\n");
}

/**
 * TypeScript declarations for every component's props, documented from the
 * catalog. Docgen (and so the Storybook manifest agents read) takes a prop's
 * description and default from these JSDoc comments; a mapped type over the
 * definitions carries none. A type check at the end fails the build if a
 * declaration and its definitions ever disagree.
 */
export function propTypesSource(): string {
  const declarations: string[] = [];
  const checks: string[] = [];
  const exports = Object.entries(components as Record<string, unknown>)
    .filter((entry): entry is [string, PropDefs] => isPropDefs(entry[1]))
    .sort(([a], [b]) => a.localeCompare(b));
  for (const [exportName, defs] of exports) {
    const name = ownPropsName(exportName);
    const members = Object.entries(defs).flatMap(([prop, def]) => {
      const type = tsType(def);
      return type === null
        ? []
        : [`${docComment(def, "  ")}\n  ${prop}?: ${type};`];
    });
    declarations.push(
      `export interface ${name} {\n${members.join("\n")}\n}`.replace(
        "{\n\n}",
        "{}",
      ),
    );
    const check = `Equal<${name}, PropsOf<typeof ${exportName}>>`;
    checks.push(
      check.length + 11 > 80
        ? `  Expect<\n    ${check}\n  >,`
        : `  Expect<${check}>,`,
    );
  }
  const imports = exports.map(([exportName]) => `  ${exportName},`).join("\n");
  return [
    HEADER,
    `import type {\n${imports}\n} from "./components/index.js";\nimport type { PropsOf } from "./props.js";`,
    ...declarations,
    "type Equal<A, B> =\n  (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2\n    ? true\n    : false;\ntype Expect<T extends true> = T;",
    `/** Fails to compile when a declaration above disagrees with its definitions. */\nexport type PropTypesMatchDefinitions = [\n${checks.join("\n")}\n];`,
  ]
    .join("\n\n")
    .concat("\n");
}
